pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the post_residual (Best Fit approach).
    // We penalize larger post_residuals to keep bins packed tightly.
    let mut score = post_res;

    // Penalty for creating 'dead space' that is too small for the next item or average items.
    // As progress increases, we become more aggressive in forcing tight fits.
    let dead_space_penalty = if post_res < next_item_size as f64 && next_item_size > 0 {
        (1.0 - progress) * (next_item_size as f64 - post_res).powi(2)
    } else {
        0.0
    };

    // If this is a new bin (bin_residual == bin_capacity), we penalize it based on 
    // how many bins are already open and how much space is left in existing bins.
    // Only open a new bin if the current fit quality is exceptionally poor.
    if bin_residual == bin_capacity {
        score += 50.0 + (open_bins_count as f64 * 2.0) - (mean_residual * 0.5);
    } else {
        // Reward bins that are nearing capacity to reduce the count of open bins.
        // The weight of this reward increases as we reach the end of the stream.
        let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= (fill_ratio.powi(2)) * (1.0 + progress * 5.0);

        // Add the dead space penalty derived from lookahead
        score += dead_space_penalty;
    }

    // Heuristic: If this is the only bin that fits, prioritize it strongly
    // unless the fit is extremely poor (large post_residual).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

    // Base score is the remaining space (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for creating "dead space" that is too small for any future item
    // Based on the assumption that small items are unlikely to be < 10
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - progress);
    }

    // Lookahead: If next item fits in the post_residual, prioritize this bin heavily
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // Global state awareness: If we have many open bins, prioritize tighter packing
    if open_bins_count > 5 {
        score += (open_bins_count as f64) * 2.0;
    }

    // If this is the only bin that fits the current item, prioritize it to avoid new bin creation
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New bin logic:
    // If the bin is brand new (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Only open a new bin if we have no good fits or we are late in the process
        // to avoid wasting space early on.
        score = 35.0 + (progress * 20.0);

        // If the item is very large, opening a new bin is better than ruining a tight fit
        if item_size > 70 {
            score -= 15.0;
        }
    }

    // Adjust score based on how much the bin deviates from the mean residual
    // We want to keep bins balanced to maximize future fit potential
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.5;

    score
}

