    let residual = bin_residual as f64;

    // Penalize creating "dead space" (small residuals) that are hard to fill later.
    // We use a quadratic penalty on the post_residual to favor tight fits.
    let mut score = post * post * 0.01;

    // Favor bins that are already well-utilized (lower mean_residual) to keep bin density high.
    score += (mean_residual - post) * 0.5;

    // Lookahead: if the next item is large, penalize small residuals that won't fit it.
    if next_item_size > 0 {
        if post < next_item_size as f64 && post > 0.0 {
            // Penalty for stranding space that cannot accommodate the known next item
            score += (next_item_size as f64 - post) * 1.5;
        }
    }

    // Dynamic thresholding: as we reach the end of the stream, prioritize closing bins
    // by heavily penalizing the opening of new bins (residual == capacity).
    if bin_residual == bin_capacity {
        // The "New Bin" penalty increases as we progress to force packing into existing bins.
        score += 25.0 + (progress * 50.0);
    } else {
        // Reward bins that have just enough space to avoid opening new ones.
        // If this is the last fitting bin, give it a significant priority boost.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    // Non-linear coupling: dampen the impact of residuals as the bin gets fuller
    // to prevent over-optimization of empty bins early on.
    score *= 1.0 + (progress * (residual / bin_capacity as f64));

    score
}

