pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic: Harmonic-Weighted Best-Fit with Lookahead Pressure
    // Objective: Minimize post_residual while avoiding "fragmentation traps"
    // where small residuals make it impossible to fit future items.

    let mut score = post_residual as f64;

    // 1. Penalize creating "Dead Space" (residuals < 10 are often useless given min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Harmonic Class logic: Reward residuals that align with common item size clusters
    // We favor residuals that are multiples of 25 (e.g., 0, 25, 50) as they accommodate 
    // standard item sizes effectively.
    score -= ((post_residual % 25) as f64) * 0.5;

    // 3. Lookahead Pressure: If next item is large, avoid bins that would be too small 
    // to accommodate it (Greedy anticipatory fit)
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 30.0;
        } else {
            // Reward bins that leave exactly enough space for the next item
            score -= (post_residual - next_item_size) as f64 * 0.2;
        }
    }

    // 4. Open-Bin Efficiency: Penalize opening new bins unless necessary
    // Only open a new bin if the current bin is "too full" to be useful for future items
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // High penalty for opening a new bin if an existing one works
            score += 60.0;
        } else {
            // Baseline cost for a new bin
            score += 10.0;
        }
    }

    // 5. Global state normalization:
    // As the stream nears completion, favor filling existing bins more aggressively
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (small residuals that cannot fit common items)
    // If the post_residual is less than 10, it's likely wasted space.
    if post_residual < 10 {
        score += 50.0;
    }

    // 2. Aggressive 2-step lookahead: 
    // If we can perfectly or near-perfectly fit the next item, reward this bin.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        // Reward if next_item_size fits well in the remaining space
        if post_residual >= next_item_size {
            score -= (100.0 - diff) * 0.8;
        }
    }

    // 3. Global efficiency:
    // If we are late in the stream, prioritize filling existing bins (lower mean_residual)
    // to avoid leaving partially filled bins stranded.
    let progress = step_index as f64 / total_items as f64;
    score += (mean_residual * progress) * 0.5;

    // 4. New Bin Constraint:
    // If this is a new bin (bin_residual == bin_capacity), penalize it 
    // unless fitting_bins_count is very low, suggesting we are forced to open one.
    if bin_residual == bin_capacity {
        score += 45.0 - (fitting_bins_count as f64 * 5.0);
    }

    // 5. Prefer tighter fits (Best Fit principle)
    // Small post_residual is good, but not if it creates "dead space" (handled in step 1)
    score += post_residual as f64 * 0.1;

    score
}
